-- ==============================================
-- ARTICLE: El Lavado de Autos (el-lavado-de-autos)
-- ==============================================
DO $$
DECLARE
  v_admin_id UUID;
  v_articulo_id UUID;
BEGIN
  SELECT id INTO v_admin_id FROM perfiles WHERE rol_id = 1 LIMIT 1;
  IF v_admin_id IS NULL THEN
    SELECT id INTO v_admin_id FROM perfiles LIMIT 1;
  END IF;

  DELETE FROM articulos WHERE slug = 'el-lavado-de-autos';

  v_articulo_id := uuid_generate_v4();

  INSERT INTO articulos (
    id,
    autor_id,
    categoria_id,
    titulo,
    slug,
    contenido,
    extracto,
    imagen_destacada,
    estado,
    etiquetas,
    metadata
  ) VALUES (
    v_articulo_id,
    v_admin_id,
    NULL,
    'El Lavado de Autos',
    'el-lavado-de-autos',
    $html$<h2>📜 Descripción de El Lavado de Auto</h2><p><strong>El Lavado de Autos</strong> es una dinámica de expresión corporal, afirmación afectiva e integración grupal. Su objetivo es romper tensiones iniciales, fortalecer la autoestima y crear un clima de acogida positiva mediante el contacto físico fraterno y respetuoso entre los participantes.</p><hr><h3>🎲 ¿Cómo se juega El Lavado de Autos?</h3><ol><li><strong>Formación del Túnel:</strong> Los participantes se dividen en dos filas paralelas colocadas frente a frente, a un metro de distancia. El espacio entre las filas representa la cinta de un túnel automático de lavado de autos.</li><li><strong>Asignación de Roles:</strong> Los jóvenes ubicados en las filas representan los "cepillos y rodillos" de la máquina de lavado. El primer participante de la fila es designado como el primer "auto".</li><li><strong>El Recorrido del Auto:</strong> El "auto" avanza lentamente con los ojos cerrados o entreabiertos caminando por el medio de las filas. A su paso, sus compañeros le brindan de manera suave y respetuosa palmaditas de aliento, masajes suaves en los hombros y palabras motivadoras de bienvenida.</li><li><strong>Rotación Continua:</strong> Al llegar al final del túnel, el "auto" se incorpora como el último rodillo de la máquina, y la siguiente persona de la cabecera inicia su recorrido como nuevo auto.</li><li><strong>Reflexión Final:</strong> La dinámica concluye cuando todos los integrantes han sido "lavados". El grupo se sienta en círculo para compartir brevemente cómo se sintieron al recibir y dar afecto.</li></ol>$html$,
    'Una dinámica de integración y afirmación afectiva donde los participantes recorren un túnel fraterno recibiendo palmaditas y palabras de aliento.',
    '/uploads/actividad_lavadoAutos.webp',
    'publicado',
    ARRAY['dinamica', 'integracion', 'afectividad', 'confianza', 'autoestima'],
    $json${"areas": ["afectividad", "carácter", "creatividad"], "lugares": ["Interior", "sala"], "cantidad": "06 participantes", "duracion": "15 minutos", "unidades": ["manada", "compañía", "tropa", "avanzada"], "descargas": [], "objetivos": ["Facilitar el conocimiento entre los pares", "Fomentar un entorno de confianza", "Favorecer la comunicación en el grupo", "Crear un clima de pertenencia"], "materiales": ["Sin Materiales"], "variaciones": "Lavado de Autos con Música Suave: Se utiliza una melodía relajante de fondo mientras los autos avanzan, permitiendo un ritmo pausado y profundo.\n\nTúnel de Palabras de Aliento: Al pasar el auto, los integrantes de las filas expresan en susurros cualidades positivas del participante (ej: \"eres alegre\", \"buen compañero\", \"valiente\").\n\nLavado de Velocidad Adaptada: Para manadas pequeñas, el túnel se realiza sentado en sillas donde el niño avanza en un carrito imaginario.", "recomendaciones": "Respeto Absoluto y Sensibilidad: La regla de oro es que el contacto físico debe ser siempre suave, cuidadoso y fraternal (palmaditas en la espalda, roce suave en hombros). Jamás se permiten empujones, cosquillas ni juegos rudos.\n\nParticipación Voluntaria: Si un integrante muestra timidez o incomodidad ante el contacto físico, se le permite ser \"operador del túnel\" o caminar acompañado por un dirigente sin forzar su espacio personal.\n\nEvaluación y Cierre Emocional: Dedicar siempre unos minutos al final para que los jóvenes verbalicen sus sensaciones. Esta evaluación es clave para desinhibir al grupo y consolidar la confianza mutua.", "justificacion_areas": "El Lavado de Autos estimula la afectividad al brindar un espacio seguro para dar y recibir muestras sinceras de afecto fraterno. Fortalece el carácter al afirmar la autoestima y autoimagen positiva de cada participante, y desarrolla la creatividad expresiva mediante la comunicación gestual y la dinamización del encuentro grupal.", "objetivos_educativos": [{"id": "006c5b09-47cf-4ed8-bf25-212203261a03", "area": "Carácter", "texto": "Sé que soy capaz de hacer cosas y de hacerlas bien.", "unidad": "Compañía", "como_se_cumple": "Valorando las demostraciones de estima como un impulso para mi crecimiento personal."}, {"id": "041daaea-c4a7-472b-a613-951bd25cfa85", "area": "Carácter", "texto": "Reconozco y acepto mis errores.", "unidad": "Manada", "como_se_cumple": "Reconociéndome como un integrante valioso de la Manada al ser acogido alegremente por mis pares."}, {"id": "2f8359db-221e-4a64-b2df-2b3e7b74a2db", "area": "Afectividad", "texto": "Escucho las opiniones de las demás personas y si no estoy de acuerdo lo digo con respeto.", "unidad": "Compañía", "como_se_cumple": "Expresando muestras de afecto sinceras y cuidadosas a las integrantes de mi patrulla."}, {"id": "3621f4ae-1316-4b3e-8682-3e3c9ad381a7", "area": "Afectividad", "texto": "Mantengo mi opinión cuando estoy convencida que es correcta.", "unidad": "Compañía", "como_se_cumple": "Disfrutando el reconocimiento y las palabras estimulantes brindadas por mis compañeras."}, {"id": "3a35ddd8-f6dc-4e00-a04d-107a0825bd99", "area": "Carácter", "texto": "Escucho las críticas que me hacen los demás y reflexiono sobre ellas.", "unidad": "Compañía", "como_se_cumple": "Fortaleciendo mi sentido de pertenencia y valoración propia ante la patrulla de guías."}, {"id": "47e7e2d8-12cd-447d-8df4-251e83aa547b", "area": "Creatividad", "texto": "Trato de hablar claro y conocer nuevas palabras.", "unidad": "Manada", "como_se_cumple": "Comunicando mi estado de ánimo alegre mediante el lenguaje corporal del juego."}, {"id": "4ade9c82-6b0d-4a44-8bc6-2eb47a011ffb", "area": "Afectividad", "texto": "Digo lo que pienso con respeto hacia los demás personas.", "unidad": "Tropa", "como_se_cumple": "Recibiendo con gratitud la acogida positiva de mis compañeros al recorrer la fila."}, {"id": "62876ebe-214f-4caf-b164-664e12fd30ae", "area": "Carácter", "texto": "Me gusta participar en actividades que me ayudan a conocerme.", "unidad": "Tropa", "como_se_cumple": "Afirmando mi autoestima y confianza personal al integrarme en la fila del grupo."}, {"id": "6c2b5054-70e8-4529-957f-a8abea073918", "area": "Afectividad", "texto": "Expreso mis opiniones libremente, sin descalificar a los demás.", "unidad": "Avanzada", "como_se_cumple": "Manifestando mis sentimientos y empatía abiertamente para fortalecer el clima de confianza de la comunidad."}, {"id": "6e25f6ed-277c-41b4-9d0f-322b0a2d4c94", "area": "Afectividad", "texto": "Acepto las opiniones de mis compañeros, aunque yo piense distinto.", "unidad": "Manada", "como_se_cumple": "Ofreciendo palmaditas y gestos de cariño respetuoso a mis compañeros de seisena al pasar por el túnel del lavado."}, {"id": "981fa19b-7f60-4e0e-b2fa-16123df5e37e", "area": "Creatividad", "texto": "Expreso mis pensamientos y experiencias en el Tally.", "unidad": "Tropa", "como_se_cumple": "Compartiendo de forma natural y transparente mis emociones al finalizar la rueda de lavado."}, {"id": "a4060c60-7ce9-425b-bf2a-76941a689937", "area": "Afectividad", "texto": "Escucho las opiniones de los demás personas y si no estoy de acuerdo lo digo con respeto.", "unidad": "Tropa", "como_se_cumple": "Brindando contacto físico fraterno y respetuoso a cada participante de la patrulla."}, {"id": "b66418eb-3eee-466e-9836-457b3bb922cc", "area": "Carácter", "texto": "Sé lo que puedo hacer y lo que no puedo hacer.", "unidad": "Manada", "como_se_cumple": "Sintiéndome seguro y querido por la seisena durante la evaluación y cierre de la dinámica."}, {"id": "beb4b3e4-fe1c-4f06-af34-2c7f88202eb7", "area": "Creatividad", "texto": "Me gusta cantar y conozco muchas canciones.", "unidad": "Compañía", "como_se_cumple": "Aportando calidez y empatía para desinhibir y motivar a las compañeras."}, {"id": "c380e11a-571d-4617-924c-aa933ae30138", "area": "Carácter", "texto": "Soy capaz de criticarme.", "unidad": "Tropa", "como_se_cumple": "Aceptando con madurez y alegría las expresiones de aprecio de los demás participantes."}, {"id": "c8993915-0234-464c-934e-2a09f8c4338e", "area": "Afectividad", "texto": "Digo lo que pienso sin ofender o insultar a mis compañeros ni burlarme de ellos.", "unidad": "Manada", "como_se_cumple": "Participando con alegría y sin vergüenza al brindar y recibir las demostraciones de afecto del grupo."}, {"id": "d252cb51-c224-4528-90b3-e0288aa343dd", "area": "Creatividad", "texto": "Comparto con los demás mis inquietudes, aspiraciones y creaciones artísticas.", "unidad": "Avanzada", "como_se_cumple": "Generando un clima de distensión y encuentro auténtico al inicio de las sesiones de la comunidad."}, {"id": "d581cfa7-db1f-4b08-b4d3-525b23e418ea", "area": "Creatividad", "texto": "Participo con entusiasmo en las actividades artísticas de mi Compañía.", "unidad": "Compañía", "como_se_cumple": "Fomentando un canal de comunicación afectuoso entre las integrantes de la patrulla."}, {"id": "dea08f50-52d5-4d87-ad7f-b7dbbb2702fc", "area": "Carácter", "texto": "Me acepto tal como soy, sin dejar de mirarme críticamente.", "unidad": "Avanzada", "como_se_cumple": "Consolidando mi autoimagen positiva y seguridad personal en el entorno caminante."}, {"id": "e5eada78-3a2d-467e-8d15-da159b60552f", "area": "Creatividad", "texto": "Me gusta dibujar y pintar.", "unidad": "Manada", "como_se_cumple": "Expresando sonrisas y gestos espontáneos durante la recreación del túnel de lavado."}, {"id": "f9cea3e0-24f4-43ab-9efb-1a4541a29943", "area": "Creatividad", "texto": "Ayudo a preparar materiales para las representaciones artísticas.", "unidad": "Tropa", "como_se_cumple": "Dinamizando la actividad con entusiasmo para que todos se sientan acogidos."}]}$json$::jsonb
  );

