-- ==============================================
-- ARTICLE: Caza de Pañolines (caza-de-panolines)
-- ==============================================
DO $$
DECLARE
  v_admin_id UUID;
  v_articulo_id UUID;
BEGIN
  SELECT id INTO v_admin_id FROM perfiles WHERE rol_id = 1 LIMIT 1;
  IF v_admin_id IS NULL THEN
    SELECT id INTO v_admin_id FROM perfiles LIMIT 1;
  END IF;

  DELETE FROM articulos WHERE slug = 'caza-de-panolines';

  v_articulo_id := uuid_generate_v4();

  INSERT INTO articulos (
    id,
    autor_id,
    categoria_id,
    titulo,
    slug,
    contenido,
    extracto,
    imagen_destacada,
    estado,
    etiquetas,
    metadata
  ) VALUES (
    v_articulo_id,
    v_admin_id,
    NULL,
    'Caza de Pañolines',
    'caza-de-panolines',
    $html$<h2>📜 Descripción de La Caza de Pañolines</h2><p><strong>Caza de Pañolines</strong> es un vibrante y clásico juego scout de competencia física, velocidad, agilidad y reflejos. Los participantes se enfrentan en un cuadrilátero acotado intentando arrebatar el pañolín colocado en la cintura del oponente mientras protegen el suyo, fomentando el juego limpio y el trabajo en equipo.</p><hr><h3>🎲 ¿Cómo se juega Caza de Pañolines?</h3><ol><li><strong>Delimitación del Área:</strong> Se marca un espacio cuadrado en el césped o terreno plano. Todos los jugadores colocan un pañolín en la parte trasera de su cinturón, dejando colgar al menos dos tercios de la tela para que sea fácil de tomar.</li><li><strong>Modalidad Individual (Todos contra Todos o Torneo):</strong> A la señal del dirigente, los jugadores se desplazan dentro del perímetro buscando quitar el pañolín de sus oponentes sin golpear ni realizar agarres bruscos. Quien pierde su pañolín queda temporalmente eliminado o entrega un punto.</li><li><strong>Modalidad en Cuña (Ciempiés de Patrulla):</strong> La patrulla o equipo de 6 integrantes forma una fila tomada firmemente de la cintura. El último participante de la fila lleva el pañolín. La patrulla debe moverse como un ciempiés coordinado para intentar quitar el pañolín de la cuña rival sin desarmar su propia formación.</li><li><strong>Cierre:</strong> Gana el participante o la patrulla que acumule más pañolines al finalizar el tiempo estipulado.</li></ol>$html$,
    'Un dinámico juego físico scout de agilidad, reflejos y juego limpio donde los competidores buscan arrebatar el pañolín del oponente.',
    '/uploads/actividad_cazaPanolines.webp',
    'publicado',
    ARRAY['juego-fisico', 'agilidad', 'panolines', 'patrulla', 'exterior'],
    $json${"areas": ["corporalidad", "carácter", "creatividad"], "lugares": ["Exterior", "campo delimitado"], "cantidad": "06 participantes", "duracion": "20 minutos", "unidades": ["manada", "compañía", "tropa", "avanzada"], "descargas": [], "objetivos": ["Refuerzo de habilidades físicas", "Estimular la agilidad mental", "Fomentar un entorno de confianza", "Favorecer el trabajo en equipo"], "materiales": ["Pañolines"], "variaciones": "Pelea de Pañolín en el Tobillo: El pañolín se ata suavemente alrededor de un tobillo. Esta variante exige mayor agilidad de piernas, giros rápidos y flexibilidad.\n\nDesafío por Parejas Espalda con Espalda: Dos scouts se toman de los brazos por la espalda e intentan quitar los pañolines de otras parejas sin romper el agarre de sus brazos.\n\nBatalla Nocturna con Linternas: Se realiza al atardecer utilizando pañolines fluorescentes o reflectantes para agudizar la visión periférica.", "recomendaciones": "Seguridad y Juego Limpio: Los dirigentes deben recalcar que está strictly prohibido el juego rudo, empujones, zancadillas o agarres de ropa. Solo se permite el tirón limpio sobre la tela del pañolín.\n\nTerreno Adecuado: Jugar siempre sobre superficies blandas (césped o arena) libres de piedras, hoyos o troncos para evitar caídas o torceduras.\n\nInclusividad: Ajustar el tamaño del cuadrilátero según la cantidad de participantes para asegurar dinamismo y evitar aglomeraciones complejas.", "justificacion_areas": "La Caza de Pañolines estimula la corporalidad al desarrollar velocidad de reacción, coordinación y equilibrio en terreno abierto. Fortalece el carácter al promover el respeto riguroso a las reglas de juego limpio y la aceptación alegre del resultado, y desarrolla la creatividad táctica al idear estrategias de amago y defensa en equipo.", "objetivos_educativos": [{"id": "418f2b77-f15b-405a-95bd-8033c0b6a4c2", "area": "Creatividad", "texto": "Puedo contar con detalles las anécdotas y aventuras que hemos tenido en la Manada.", "unidad": "Manada", "como_se_cumple": "Ideando fintas y amagos corporales sencillos durante el duelo."}, {"id": "d5b111f1-5f6f-4716-8a02-e1826d653c59", "area": "Corporalidad", "texto": "Participo en los juegos, excursiones y campamentos que organiza mi patrulla.", "unidad": "Compañía", "como_se_cumple": "Demostrando equilibrio y destreza corporal al capturar el pañolín de mis oponentes."}, {"id": "b12da732-d736-480c-82b8-95b312316390", "area": "Corporalidad", "texto": "Me esfuerzo por mejorar mi rendimiento en el deporte que practico y sé ganar y perder.", "unidad": "Compañía", "como_se_cumple": "Coordinando movimientos ágiles con mi patrulla en la modalidad de ciempiés."}, {"id": "e1b7276f-4fd2-4c39-a32a-bd7fadbee702", "area": "Creatividad", "texto": "Doy mi opinión sobre las cosas que me pasan.", "unidad": "Compañía", "como_se_cumple": "Desarrollando agilidad de pensamiento para reaccionar velozmente en espacios reducidos."}, {"id": "9f30f035-9179-4ac4-acfb-bea0e169e97a", "area": "Creatividad", "texto": "Propongo temas para discutir en mi patrulla.", "unidad": "Compañía", "como_se_cumple": "Proponiendo tácticas creativas de protección del pañolín en equipo."}, {"id": "117bbf3f-7e3d-4c61-b305-821609bf2e5a", "area": "Carácter", "texto": "Contribuyo al ambiente de alegría de mi Compañía.", "unidad": "Compañía", "como_se_cumple": "Riendo y compartiendo momentos divertidos con mis compañeras de equipo."}, {"id": "25b24d3a-9d47-44af-b460-680508e644f3", "area": "Carácter", "texto": "Soy alegre.", "unidad": "Compañía", "como_se_cumple": "Enfrentando los desafíos físicos con optimismo y respeto por las oponentes."}, {"id": "58b4936a-816e-4d17-8d0a-c92d0606009d", "area": "Corporalidad", "texto": "Participo en los juegos, excursiones y campamentos que organiza mi patrulla.", "unidad": "Tropa", "como_se_cumple": "Ejercitando mi resistencia física y velocidad de reacción en el torneo de pañolines."}, {"id": "6768d60a-187e-4bbf-97b9-cdc25a316030", "area": "Corporalidad", "texto": "Ayudo a preparar los juegos, excursiones y campamentos de mi patrulla y mi Tropa.", "unidad": "Tropa", "como_se_cumple": "Esforzándome por mejorar mi rendimiento físico manteniendo el juego limpio al ganar y perder."}, {"id": "49ae6ac6-be8f-4f2c-8b3e-6711d041181f", "area": "Creatividad", "texto": "Doy mi opinión sobre las cosas que me pasan.", "unidad": "Tropa", "como_se_cumple": "Anticipando los movimientos del rival y adaptando mi posición táctica en el terreno."}, {"id": "cf530cf9-73a6-4423-a075-79be433fe96c", "area": "Creatividad", "texto": "Propongo temas para discutir en mi patrulla.", "unidad": "Tropa", "como_se_cumple": "Diseñando estrategias de defensa y ataque coordinado en la formación en cuña."}, {"id": "4d66ed86-48ec-4801-bd0a-e5c8d023c8cd", "area": "Carácter", "texto": "Enfrento y resuelvo mis dificultades con alegría.", "unidad": "Tropa", "como_se_cumple": "Aceptando los resultados del torneo con espíritu fraterno y sentido del humor."}, {"id": "9a38e454-f93a-40a5-9f68-e500ba7e0655", "area": "Carácter", "texto": "Comparto mi alegría con mis amigos, amigos y familia.", "unidad": "Tropa", "como_se_cumple": "Promoviendo el buen ánimo y el compañerismo en las batallas por patrulla."}, {"id": "7200435f-b020-46fc-b323-8249048b1d18", "area": "Corporalidad", "texto": "Participo en la organización de juegos y actividades recreativas para los demás.", "unidad": "Avanzada", "como_se_cumple": "Liderando dinámicas físicas de alta intensidad y competencia sana en la comunidad."}, {"id": "3cdf4b56-b55f-4878-b3fa-da32a7200ca4", "area": "Creatividad", "texto": "Soy capaz de sintetizar, criticar, proponer y apreciar las opiniones de los demás.", "unidad": "Avanzada", "como_se_cumple": "Analizando patrones de movimiento del oponente para resolver situaciones complejas de competencia."}, {"id": "4b2e406f-2d78-4039-9ce2-4ccb743eb553", "area": "Carácter", "texto": "Soy capaz de reírme de mis propios absurdos.", "unidad": "Avanzada", "como_se_cumple": "Fomentando un clima recreativo de camaradería y juego limpio."}, {"id": "4bf1e3dd-7f21-4c24-962d-9d6d64e32f25", "area": "Corporalidad", "texto": "Me gusta hacer actividades al aire libre.", "unidad": "Manada", "como_se_cumple": "Desplegando agilidad y reflejos rápidos al esquivar a mis compañeros en la caza de pañolines."}, {"id": "5d2d48ed-c461-4a8e-9048-cceecd3de2e2", "area": "Corporalidad", "texto": "Me gusta jugar con otros niños y niñas y respeto las reglas de los juegos.", "unidad": "Manada", "como_se_cumple": "Jugando con entusiasmo respetando las reglas del juego de pañolines."}, {"id": "ec280dd0-2d80-4b84-86ad-2d362da14886", "area": "Creatividad", "texto": "Me gusta participar en juegos de observación.", "unidad": "Manada", "como_se_cumple": "Reaccionando con rapidez de reflejos para esquivar los intentos de mis compañeros."}, {"id": "8c1cbf88-6e1d-496b-b789-9e0b767c8814", "area": "Carácter", "texto": "Casi siempre estoy alegre.", "unidad": "Manada", "como_se_cumple": "Disfrutando alegremente del juego sin molestarme si me quitan el pañolín."}, {"id": "d408da3c-207d-4442-a891-8f50efbeecb1", "area": "Carácter", "texto": "Enfrento las dificultades con buen ánimo.", "unidad": "Manada", "como_se_cumple": "Manteniendo una actitud positiva y risueña durante toda la actividad."}]}$json$::jsonb
  );

