-- ==============================================
-- ARTICLE: El Abrazo Musical (el-abrazo-musical)
-- ==============================================
DO $$
DECLARE
  v_admin_id UUID;
  v_articulo_id UUID;
BEGIN
  SELECT id INTO v_admin_id FROM perfiles WHERE rol_id = 1 LIMIT 1;
  IF v_admin_id IS NULL THEN
    SELECT id INTO v_admin_id FROM perfiles LIMIT 1;
  END IF;

  DELETE FROM articulos WHERE slug = 'el-abrazo-musical';

  v_articulo_id := uuid_generate_v4();

  INSERT INTO articulos (
    id,
    autor_id,
    categoria_id,
    titulo,
    slug,
    contenido,
    extracto,
    imagen_destacada,
    estado,
    etiquetas,
    metadata
  ) VALUES (
    v_articulo_id,
    v_admin_id,
    NULL,
    'El Abrazo Musical',
    'el-abrazo-musical',
    $html$<h2>📜 Descripción de El Abrazo Musical</h2><p><strong>El Abrazo Musical</strong> es una dinámica de integración, rompehielos y afianzamiento afectivo grupal. A través del ritmo y el movimiento espontáneo, invita a los participantes a romper barreras de timidez, construir confianza y vivenciar el valor de la acogida colectiva.</p><hr><h3>🎲 ¿Cómo se juega El Abrazo Musical?</h3><ol><li><strong>Inicio con Música:</strong> Se reproduce una canción alegre mientras todos los participantes bailan y se desplazan libremente por el espacio.</li><li><strong>Abrazos por Parejas:</strong> Cuando la música se detiene repentinamente, cada jugador debe buscar a un compañero para darse un abrazo fraternal de bienvenida.</li><li><strong>Abrazos Progresivos:</strong> La música vuelve a sonar y todos continúan bailando. En las siguientes pausas, el dirigente indica aumentar el número de integrantes por abrazo (grupos de 3, luego 4, 5 y 6 personas).</li><li><strong>El Gran Abrazo Colectivo:</strong> La dinámica concluye cuando toda la unidad se une en un único, cálido y gran abrazo grupal al silenciarse la música por última vez.</li></ol>$html$,
    'Una alegre dinámica de integración y afianzamiento afectivo donde el grupo baila al ritmo de la música y se une en abrazos colectivos.',
    '/uploads/actividad_abrazoMusical.webp',
    'publicado',
    ARRAY['dinamica', 'integracion', 'afectividad', 'confianza', 'interior'],
    $json${"areas": ["afectividad", "sociabilidad", "carácter"], "lugares": ["Interior", "sala"], "cantidad": "06 participantes", "duracion": "15 minutos", "unidades": ["manada", "compañía", "tropa"], "descargas": [], "objetivos": ["Favorecer la comunicación en el grupo", "Crear un clima de pertenencia", "Fomentar un entorno de confianza", "Facilitar el conocimiento entre los pares"], "materiales": ["Parlante", "Reproductor de Música"], "variaciones": "Abrazos con Gestos Temáticos: En cada pausa musical, el dirigente indica una consigna de saludo antes del abrazo (ej: saludo scout, choque de codos o cara de sorpresa).\n\nBaile en Estilos Variados: Cambiar los géneros musicales (cumbia, rock, folclore) en cada ronda para incentivar la creatividad corporal y las risas.\n\nAbrazo a Ciegas (Ojos Cerrados): Los participantes se desplazan en silencio con los ojos cerrados hasta encontrar las manos de un compañero para abrazarse.", "recomendaciones": "Sensibilidad y Respeto Personal: Velar siempre por que el contacto físico sea sumamente respetuoso, suave y fraterno. Jamás forzar a un participante si muestra timidez o reticencia inicial.\n\nClima de Acogida Inclusiva: Incentivar a los jóvenes a buscar deliberadamente a compañeros de distintas seisenas o patrullas con quienes no hayan conversado aún.\n\nEvaluación Corta de Cierre: Dedicar dos minutos al final sentado en círculo para comentar la sensación de pertenencia y el valor de ser recibidos con alegría por el grupo.", "justificacion_areas": "El Abrazo Musical estimula la afectividad al brindar un entorno seguro y alegre para manifestar muestras sinceras de afecto fraterno. Desarrolla la sociabilidad al impulsar la integración inclusiva de todos los participantes sin distinciones, y fortalece el carácter al promover la autoestima y la desinhibición a través de la expresión corporal libre.", "objetivos_educativos": [{"id": "0d3af46a-d64c-4e59-a765-1f72dc41ba76", "area": "Sociabilidad", "texto": "Ayudo a mi patrulla en los compromisos que tomamos.", "unidad": "Tropa", "como_se_cumple": "Asumiendo un rol activo para cohesionar a la patrulla en un abrazo común."}, {"id": "117bbf3f-7e3d-4c61-b305-821609bf2e5a", "area": "Carácter", "texto": "Contribuyo al ambiente de alegría de mi Compañía.", "unidad": "Compañía", "como_se_cumple": "Compartiendo momentos divertidos y distendidos con mis pares."}, {"id": "25b24d3a-9d47-44af-b460-680508e644f3", "area": "Carácter", "texto": "Soy alegre.", "unidad": "Compañía", "como_se_cumple": "Enfrentando los juegos de integración con soltura y actitud positiva."}, {"id": "2f8359db-221e-4a64-b2df-2b3e7b74a2db", "area": "Afectividad", "texto": "Escucho las opiniones de las demás personas y si no estoy de acuerdo lo digo con respeto.", "unidad": "Compañía", "como_se_cumple": "Manifestando empatía y calidez en los encuentros de patrulla."}, {"id": "3621f4ae-1316-4b3e-8682-3e3c9ad381a7", "area": "Afectividad", "texto": "Mantengo mi opinión cuando estoy convencida que es correcta.", "unidad": "Compañía", "como_se_cumple": "Promoviendo relaciones afectivas sanas y respetuosas en la unidad."}, {"id": "4ade9c82-6b0d-4a44-8bc6-2eb47a011ffb", "area": "Afectividad", "texto": "Digo lo que pienso con respeto hacia los demás personas.", "unidad": "Tropa", "como_se_cumple": "Facilitando un clima de confianza fraterna donde todos se sientan valorados."}, {"id": "4d66ed86-48ec-4801-bd0a-e5c8d023c8cd", "area": "Carácter", "texto": "Enfrento y resuelvo mis dificultades con alegría.", "unidad": "Tropa", "como_se_cumple": "Viviendo la dinámica con sentido del humor y alegría compartida."}, {"id": "5cbe35dc-d15b-4070-9a36-5b0e652c7946", "area": "Sociabilidad", "texto": "Respeto las opiniones de los demás.", "unidad": "Manada", "como_se_cumple": "Incluyendo activamente a los lobatos más tímidos en el círculo."}, {"id": "6e25f6ed-277c-41b4-9d0f-322b0a2d4c94", "area": "Afectividad", "texto": "Acepto las opiniones de mis compañeros, aunque yo piense distinto.", "unidad": "Manada", "como_se_cumple": "Brindando abrazos respetuosos y cariñosos a mis compañeros al detenerse la música."}, {"id": "8c1cbf88-6e1d-496b-b789-9e0b767c8814", "area": "Carácter", "texto": "Casi siempre estoy alegre.", "unidad": "Manada", "como_se_cumple": "Disfrutando del baile y el ritmo musical con espontaneidad y risas."}, {"id": "944660c8-0093-4181-ba2c-5f95cc74ba47", "area": "Sociabilidad", "texto": "No me gusta cuando no se respetan los derechos humanos y lo digo.", "unidad": "Compañía", "como_se_cumple": "Velando por el bienestar y la comodidad emocional de las compañeras."}, {"id": "9a38e454-f93a-40a5-9f68-e500ba7e0655", "area": "Carácter", "texto": "Comparto mi alegría con mis amigos, amigos y familia.", "unidad": "Tropa", "como_se_cumple": "Fomentando el optimismo y la buena energía al dinamizar el encuentro."}, {"id": "a3d7abdf-ca3b-42b8-92b5-403958fb537c", "area": "Sociabilidad", "texto": "Procuro que respetemos a nuestras compañeros, cualquiera sea su manera de ser.", "unidad": "Tropa", "como_se_cumple": "Promoviendo la inclusión de todos los integrantes sin distinciones."}, {"id": "a4060c60-7ce9-425b-bf2a-76941a689937", "area": "Afectividad", "texto": "Escucho las opiniones de los demás personas y si no estoy de acuerdo lo digo con respeto.", "unidad": "Tropa", "como_se_cumple": "Expresando acogida sincera al integrar a nuevos compañeros en el abrazo progresivo."}, {"id": "c8993915-0234-464c-934e-2a09f8c4338e", "area": "Afectividad", "texto": "Digo lo que pienso sin ofender o insultar a mis compañeros ni burlarme de ellos.", "unidad": "Manada", "como_se_cumple": "Recibiendo con alegría las muestras de afecto grupal durante la dinámica."}, {"id": "cfa10133-c25c-4deb-aebe-a00f8fe3f7ef", "area": "Sociabilidad", "texto": "Comparto lo que tengo con mis compañeros y compañeras.", "unidad": "Manada", "como_se_cumple": "Buscando que ningún seisenero quede fuera del abrazo grupal."}, {"id": "d408da3c-207d-4442-a891-8f50efbeecb1", "area": "Carácter", "texto": "Enfrento las dificultades con buen ánimo.", "unidad": "Manada", "como_se_cumple": "Participando con entusiasmo sin sentir vergüenza al expresarme corporalmente."}, {"id": "fce82191-77ea-444b-89d9-e33b62a323a5", "area": "Sociabilidad", "texto": "Procuro que respetemos a nuestras compañeras, cualquiera sea su manera de ser.", "unidad": "Compañía", "como_se_cumple": "Fomentando el espíritu de cuerpo y la integración solidaria."}]}$json$::jsonb
  );

