-- ==============================================
-- ARTICLE: Pelea de Gallos (duelo-de-gallitos)
-- ==============================================
DO $$
DECLARE
  v_admin_id UUID;
  v_articulo_id UUID;
BEGIN
  SELECT id INTO v_admin_id FROM perfiles WHERE rol_id = 1 LIMIT 1;
  IF v_admin_id IS NULL THEN
    SELECT id INTO v_admin_id FROM perfiles LIMIT 1;
  END IF;

  DELETE FROM articulos WHERE slug = 'duelo-de-gallitos';

  v_articulo_id := uuid_generate_v4();

  INSERT INTO articulos (
    id,
    autor_id,
    categoria_id,
    titulo,
    slug,
    contenido,
    extracto,
    imagen_destacada,
    estado,
    etiquetas,
    metadata
  ) VALUES (
    v_articulo_id,
    v_admin_id,
    NULL,
    'Pelea de Gallos',
    'duelo-de-gallitos',
    $html$<h2>📜 Descripción de la Pelea de Gallos</h2><p><strong>Pelea de Gallos</strong> es un divertido y clásico juego scout de equilibrio, agilidad física y fuerza suave por parejas. Se realiza en terrenos blandos al aire libre donde los competidores desafían su estabilidad en posición de cuclillas sin perder el control.</p><hr><h3>🎲 ¿Cómo se juega la Pelea de Gallos?</h3><ol><li><strong>Posición Inicial:</strong> Dos participantes se ubican frente a frente a un metro de distancia dentro de un pequeño círculo marcado en el césped. Ambos se colocan en cuclillas tomándose los tobillos o cruzando los brazos sobre el pecho.</li><li><strong>El Duelo:</strong> A la señal del dirigente, ambos jugadores avanzan en cuclillas e intentan desestabilizar al oponente mediante suaves empujones con los hombros o las palmas de las manos.</li><li><strong>Condiciones de Victoria:</strong> Un jugador gana la ronda si su oponente pierde el equilibrio tocando el suelo con las rodillas o manos, se sale del círculo marcado, o suelta el agarre de los tobillos.</li><li><strong>Rotación por Rondas:</strong> Se realizan duelos cortos de un minuto y los ganadores avanzan de ronda en un torneo amistoso por patrullas.</li></ol>$html$,
    'Un divertido juego scout de agilidad, fuerza suave y equilibrio en cuclillas donde los competidores buscan desestabilizar al oponente.',
    '/uploads/actividad_dueloGallitos.webp',
    'publicado',
    ARRAY['juego-fisico', 'equilibrio', 'parejas', 'exterior', 'agilidad'],
    $json${"areas": ["corporalidad", "carácter", "sociabilidad"], "lugares": ["Exterior", "campo delimitado"], "cantidad": "02 participantes", "duracion": "15 minutos", "unidades": ["compañía", "tropa"], "descargas": [], "objetivos": ["Refuerzo de habilidades físicas", "Estimular la agilidad mental", "Fomentar un entorno de confianza", "Favorecer el trabajo en equipo"], "materiales": ["Sin Materiales"], "variaciones": "Gallitos sobre un Pie: En lugar de estar en cuclillas, los participantes se sostienen sobre un solo pie tomándose el otro tobillo con una mano.\n\nDuelo por Equipos (Todos contra Todos): Todas las parejas entran al cuadrilátero simultáneamente en cuclillas; gana el último \"gallito\" que quede en pie sin caer.\n\nDuelo de Pañolín: Cada competidor lleva un pañolín colocado en el hombro; el objetivo es quitar el pañolín del rival sin perder el equilibrio en cuclillas.", "recomendaciones": "Supervisión Directa de Seguridad: Es indispensable verificar que los participantes no utilicen cabezazos, empujones violentos ni zancadillas. Solo se permite el empuje limpio de palmas y hombros.\n\nSuperficie Adecuada: Realizar el juego exclusivamente sobre césped mullido, arena o colchonetas recreativas para amortiguar suavemente las caídas.\n\nFomento del Juego Limpio: Felicitar la caballerosidad scout y la risa compartida tras cada duelo, promoviendo el estrechamiento de manos al finalizar.", "justificacion_areas": "Duelo de Gallitos estimula la corporalidad al poner a prueba la fuerza suave, la estabilidad del centro de gravedad y el equilibrio en cuclillas. Fortalece el carácter al promover el sentido del humor ante las caídas cómicas y el respeto a las reglas, y desarrolla la sociabilidad al afianzar la caballerosidad y la convivencia limpia.", "objetivos_educativos": [{"id": "d5b111f1-5f6f-4716-8a02-e1826d653c59", "area": "Corporalidad", "texto": "Participo en los juegos, excursiones y campamentos que organiza mi patrulla.", "unidad": "Compañía", "como_se_cumple": "Demostrando destreza corporal y coordinación motriz en los empujes de hombros."}, {"id": "b12da732-d736-480c-82b8-95b312316390", "area": "Corporalidad", "texto": "Me esfuerzo por mejorar mi rendimiento en el deporte que practico y sé ganar y perder.", "unidad": "Compañía", "como_se_cumple": "Perfeccionando el control del centro de gravedad y el equilibrio dinámico."}, {"id": "fce82191-77ea-444b-89d9-e33b62a323a5", "area": "Sociabilidad", "texto": "Procuro que respetemos a nuestras compañeras, cualquiera sea su manera de ser.", "unidad": "Compañía", "como_se_cumple": "Fomentando la solidaridad y el fair play en las actividades al aire libre."}, {"id": "117bbf3f-7e3d-4c61-b305-821609bf2e5a", "area": "Carácter", "texto": "Contribuyo al ambiente de alegría de mi Compañía.", "unidad": "Compañía", "como_se_cumple": "Riendo y viviendo la experiencia con optimismo y desinhibición."}, {"id": "25b24d3a-9d47-44af-b460-680508e644f3", "area": "Carácter", "texto": "Soy alegre.", "unidad": "Compañía", "como_se_cumple": "Enfrentando los desafíos físicos con caballerosidad y madurez emocional."}, {"id": "944660c8-0093-4181-ba2c-5f95cc74ba47", "area": "Sociabilidad", "texto": "No me gusta cuando no se respetan los derechos humanos y lo digo.", "unidad": "Compañía", "como_se_cumple": "Velando por el bienestar y el juego limpio de las oponentes."}, {"id": "58b4936a-816e-4d17-8d0a-c92d0606009d", "area": "Corporalidad", "texto": "Participo en los juegos, excursiones y campamentos que organiza mi patrulla.", "unidad": "Tropa", "como_se_cumple": "Fortaleciendo mi resistencia y estabilidad al competir fraternalmente por parejas."}, {"id": "6768d60a-187e-4bbf-97b9-cdc25a316030", "area": "Corporalidad", "texto": "Ayudo a preparar los juegos, excursiones y campamentos de mi patrulla y mi Tropa.", "unidad": "Tropa", "como_se_cumple": "Esforzándome por superar mis capacidades físicas manteniendo el juego limpio."}, {"id": "4d66ed86-48ec-4801-bd0a-e5c8d023c8cd", "area": "Carácter", "texto": "Enfrento y resuelvo mis dificultades con alegría.", "unidad": "Tropa", "como_se_cumple": "Asumiendo los resultados de los duelos con espíritu deportivo y sentido del humor."}, {"id": "9a38e454-f93a-40a5-9f68-e500ba7e0655", "area": "Carácter", "texto": "Comparto mi alegría con mis amigos, amigos y familia.", "unidad": "Tropa", "como_se_cumple": "Fomentando el compañerismo y el respeto mutuo durante la competencia por patrullas."}, {"id": "a3d7abdf-ca3b-42b8-92b5-403958fb537c", "area": "Sociabilidad", "texto": "Procuro que respetemos a nuestras compañeros, cualquiera sea su manera de ser.", "unidad": "Tropa", "como_se_cumple": "Promoviendo el respeto y la consideración por la integridad del rival."}, {"id": "0d3af46a-d64c-4e59-a765-1f72dc41ba76", "area": "Sociabilidad", "texto": "Ayudo a mi patrulla en los compromisos que tomamos.", "unidad": "Tropa", "como_se_cumple": "Apoyando y animando con entusiasmo a los integrantes de la patrulla."}]}$json$::jsonb
  );

  INSERT INTO articulo_categorias (articulo_id, categoria_id) VALUES (v_articulo_id, 1) ON CONFLICT DO NOTHING;
  INSERT INTO articulo_categorias (articulo_id, categoria_id) VALUES (v_articulo_id, 7) ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, 'd5b111f1-5f6f-4716-8a02-e1826d653c59', 'Demostrando destreza corporal y coordinación motriz en los empujes de hombros.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, 'b12da732-d736-480c-82b8-95b312316390', 'Perfeccionando el control del centro de gravedad y el equilibrio dinámico.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, 'fce82191-77ea-444b-89d9-e33b62a323a5', 'Fomentando la solidaridad y el fair play en las actividades al aire libre.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '117bbf3f-7e3d-4c61-b305-821609bf2e5a', 'Riendo y viviendo la experiencia con optimismo y desinhibición.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '25b24d3a-9d47-44af-b460-680508e644f3', 'Enfrentando los desafíos físicos con caballerosidad y madurez emocional.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '944660c8-0093-4181-ba2c-5f95cc74ba47', 'Velando por el bienestar y el juego limpio de las oponentes.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '58b4936a-816e-4d17-8d0a-c92d0606009d', 'Fortaleciendo mi resistencia y estabilidad al competir fraternalmente por parejas.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '6768d60a-187e-4bbf-97b9-cdc25a316030', 'Esforzándome por superar mis capacidades físicas manteniendo el juego limpio.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '4d66ed86-48ec-4801-bd0a-e5c8d023c8cd', 'Asumiendo los resultados de los duelos con espíritu deportivo y sentido del humor.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '9a38e454-f93a-40a5-9f68-e500ba7e0655', 'Fomentando el compañerismo y el respeto mutuo durante la competencia por patrullas.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, 'a3d7abdf-ca3b-42b8-92b5-403958fb537c', 'Promoviendo el respeto y la consideración por la integridad del rival.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '0d3af46a-d64c-4e59-a765-1f72dc41ba76', 'Apoyando y animando con entusiasmo a los integrantes de la patrulla.') ON CONFLICT DO NOTHING;

END $$;


-- ==============================================
-- ARTICLE: Caza Globos (caza-globos)
-- ==============================================
DO $$
DECLARE
  v_admin_id UUID;
  v_articulo_id UUID;
BEGIN
  SELECT id INTO v_admin_id FROM perfiles WHERE rol_id = 1 LIMIT 1;
  IF v_admin_id IS NULL THEN
    SELECT id INTO v_admin_id FROM perfiles LIMIT 1;
  END IF;

  DELETE FROM articulos WHERE slug = 'caza-globos';

  v_articulo_id := uuid_generate_v4();

  INSERT INTO articulos (
    id,
    autor_id,
    categoria_id,
    titulo,
    slug,
    contenido,
    extracto,
    imagen_destacada,
    estado,
    etiquetas,
    metadata
  ) VALUES (
    v_articulo_id,
    v_admin_id,
    NULL,
    'Caza Globos',
    'caza-globos',
    $html$<h2>📜 Descripción de Caza Globos</h2><p>Caza Globos es un juego de alta energía que combina la dinámica del balonmano con la emoción de proteger un globo atado al tobillo. Cada participante lleva un globo inflado como su vida y debe intentar reventar los globos de los rivales mientras maneja una pelota. Es una actividad perfecta para desfogar energías, desarrollar reflejos y fomentar la sana competencia en un ambiente de diversión grupal.</p><hr><h3>🎲 ¿Cómo se juega Caza Globos?</h3><ol><li><strong>Preparación:</strong> Cada participante recibe un globo inflado que se ata a su tobillo con una cuerda o elástico, dejando el globo colgando aproximadamente a 10 cm del suelo.</li><li><strong>Formación de equipos:</strong> Se dividen los participantes en dos equipos equilibrados. Se delimita el campo de juego con dimensiones similares a una cancha de balonmano reducida.</li><li><strong>Inicio del juego:</strong> El juego funciona como balonmano normal: se pasa la pelota con las manos, se avanza hacia la portería rival y se intenta marcar gol.</li><li><strong>Regla del globo:</strong> La particularidad es que cualquier jugador que lleve la pelota puede ser atacado por un rival intentando pisarle el globo. Si el globo se revienta, ese jugador queda eliminado temporalmente.</li><li><strong>Recuperación de vida:</strong> El jugador sin globo debe salir del campo, buscar un nuevo globo, inflarlo y volver a incorporarse al juego.</li><li><strong>Límite de vidas:</strong> Cada jugador puede recuperar su globo un máximo de tres veces. Después de la tercera eliminación, queda fuera del partido.</li><li><strong>Portero protegido:</strong> El portero puede intentar reventar el globo de cualquier jugador rival que entre en el área de portería, pero no puede quitarle la vida a un jugador que no lleve la pelota.</li><li><strong>Falta por agresión:</strong> Si un jugador revienta el globo de un rival que NO lleva la pelota, debe devolverle el globo inmediatamente como penalización.</li><li><strong>Victoria:</strong> Gana el equipo que logre más goles al finalizar el tiempo establecido, o el equipo que elimine a todos los rivales primero.</li></ol>$html$,
    'Juego de balonmano donde cada jugador protege un globo atado a su tobillo mientras intenta reventar los rivales.',
    '/uploads/caza-globos.webp',
    'publicado',
    ARRAY['juego', 'cooperativo', 'globos', 'balonmano', 'reflejos'],
    $json${"areas": ["corporalidad"], "lugares": ["Exterior", "Interior", "campo delimitado"], "cantidad": "06 participantes", "duracion": "30 minutos", "unidades": ["manada", "compania", "tropa", "avanzada"], "descargas": [], "objetivos": ["Desfogue de Energías", "Estimular la capacidad de reacción", "Favorecer el trabajo en equipo", "Fomentar la sana competencia"], "materiales": ["Globos", "Pelota de balonmano o similar", "Cuerdas o elásticos", "Conos para delimitar el campo"], "variaciones": "Variación por nivel de dificultad: Para grupos más pequeños (Manada), se puede jugar sin la pelota de balonmano, centrando el juego únicamente en la protección del globo. Los participantes corren libremente por el campo intentando pisar los globos rivales mientras protegen el propio. Gana quien conserve su globo al final del tiempo.\n\nVariación de equipos múltiples: En lugar de dos equipos, se pueden formar tres o cuatro equipos que jueguen simultáneamente en un campo más amplio, creando alianzas temporales y traiciones estratégicas que añaden complejidad al juego.\n\nVariación de globo compartido: Cada pareja de jugadores comparte un globo atado entre ambos tobillos, obligándolos a coordinar sus movimientos y desplazarse juntos, lo que refuerza la comunicación no verbal y la confianza mutua.\n\nAdaptación para clima lluvioso: Si no se puede jugar al aire libre, se adapta a un gimnasio o salón grande reduciendo el tamaño del campo y usando globos más pequeños para mayor seguridad.\n\nVariación nocturna: Se puede jugar al atardecer o de noche con linternas, añadiendo el desafío de la visibilidad reducida y convirtiendo el juego en una experiencia de acecho y observación.\n\nVariación de roles especiales: Se pueden asignar roles como el Médico (puede devolver un globo a un compañero eliminado una vez por partido) o el Capitán (si su globo se revienta, todo el equipo pierde una vida).", "recomendaciones": "Seguridad ante todo: Es fundamental revisar el terreno de juego antes de comenzar, asegurándose de que no haya piedras, ramas, baches u objetos que puedan causar tropiezos. El campo debe ser plano y libre de obstáculos. Los participantes deben llevar calzado cerrado y adecuado para correr.\n\nUso correcto de los globos: Los globos deben atarse con cuerdas o elásticos lo suficientemente largos para que no restrinjan el movimiento del tobillo, pero lo suficientemente cortos para que no se enganchen con otros jugadores. Se recomienda usar globos de colores diferentes por equipo para facilitar la identificación visual.\n\nReglas de contacto físico: Debe quedar muy claro que NO se permite empujar, agarrar o hacer contacto físico agresivo con otros jugadores. La única interacción permitida es pisar el globo del rival. Si un jugador muestra conducta agresiva, se le amonesta y, en caso de reincidencia, se le expulsa del partido.\n\nGestión de la eliminación temporal: Es importante que los dirigentes supervisen que los jugadores eliminados salgan del campo inmediatamente y no interfieran con el juego. Se puede designar una zona de reabastecimiento donde los jugadores inflan sus nuevos globos antes de reincorporarse.\n\nFomentar el espíritu deportivo: Antes del juego, recordar a todos los participantes que el objetivo principal es divertirse. Celebrar las buenas jugadas de ambos equipos y evitar que la competencia genere rivalidades negativas. Al finalizar, hacer una breve reflexión grupal sobre qué estrategias funcionaron mejor y cómo se sintieron al proteger su pañolín simbólico (el globo).\n\nAdaptación por edad: Para la Manada (7-10 años), reducir la intensidad del contacto y permitir más vidas (4-5 globos). Para Avanzada (15-17 años), se puede aumentar la complejidad añadiendo reglas tácticas como zonas de inviolabilidad o tiempos de poder especial.", "justificacion_areas": "Caza Globos desarrolla principalmente la Corporalidad en su expresión más pura: coordinación motriz fina y gruesa simultánea. Los participantes deben correr, esquivar, lanzar y proteger su globo al mismo tiempo, lo que desarrolla reflejos, equilibrio, conciencia espacial y control del propio cuerpo en movimiento. La necesidad de mantener el globo intacto mientras se ejecutan acciones deportivas complejas (pasar, recibir, lanzar a portería) exige una integración corporal completa que va más allá del juego deportivo convencional. Además, la dinámica de vidas limitadas (tres globos máximo) enseña a manejar la frustración de la eliminación temporal y a reincorporarse al grupo con motivación renovada, fortaleciendo la resiliencia física y emocional.", "objetivos_educativos": [{"id": "0765469b-caef-4457-9d6b-cb739c855402", "area": "Corporalidad", "texto": "Conozco y practico diferentes juegos y respeto sus reglas.", "unidad": "Tropa", "como_se_cumple": "Practicando Caza Globos con mi patrulla, aprendiendo sus reglas únicas que combinan balonmano con protección de globos, y respetando el juego limpio en cada partida."}, {"id": "1427451e-b8b3-493b-8525-e53298381e07", "area": "Corporalidad", "texto": "Conozco y practico diferentes juegos y respeto sus reglas.", "unidad": "Compañía", "como_se_cumple": "Aprendiendo y practicando las reglas específicas de Caza Globos, combinando balonmano con protección de globos, y respetando las normas de juego limpio con mi patrulla."}, {"id": "309c6121-94fc-43a2-b0fb-f6a975f78962", "area": "Corporalidad", "texto": "Practico deportes, conozco sus reglas y sé perder.", "unidad": "Manada", "como_se_cumple": "Jugando Caza Globos con entusiasmo, respetando todas las reglas del juego y aprendiendo a aceptar con deportividad tanto la victoria como la derrota cuando mi globo se revienta."}, {"id": "5d2d48ed-c461-4a8e-9048-cceecd3de2e2", "area": "Corporalidad", "texto": "Me gusta jugar con otros niños y niñas y respeto las reglas de los juegos.", "unidad": "Manada", "como_se_cumple": "Participando activamente en Caza Globos, donde aprendo a respetar las reglas del juego mientras me divierto corriendo, esquivando y protegiendo mi globo junto a mis compañeros de Manada."}, {"id": "7200435f-b020-46fc-b323-8249048b1d18", "area": "Corporalidad", "texto": "Participo en la organización de juegos y actividades recreativas para los demás.", "unidad": "Avanzada", "como_se_cumple": "Liderando la organización de Caza Globos para mi Avanzada y unidades menores, preparando el campo, explicando las reglas y facilitando que todos disfruten de la actividad de forma segura."}, {"id": "7c91a6b0-5a22-464b-b965-dd216859db69", "area": "Corporalidad", "texto": "Preparo juegos para distintas ocasiones.", "unidad": "Tropa", "como_se_cumple": "Organizando Caza Globos para distintas reuniones de mi Tropa, adaptando el campo, las reglas y los materiales según el espacio disponible y la cantidad de participantes."}, {"id": "a3e5dd16-5205-4d00-b79b-e14d0492e34d", "area": "Corporalidad", "texto": "Preparo juegos para distintas ocasiones.", "unidad": "Compañía", "como_se_cumple": "Colaborando en la organización y preparación de Caza Globos para mi Compañía, adaptando las reglas, el espacio y los materiales según las necesidades del grupo y la ocasión."}]}$json$::jsonb
  );

  INSERT INTO articulo_categorias (articulo_id, categoria_id) VALUES (v_articulo_id, 7) ON CONFLICT DO NOTHING;
