  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '309c6121-94fc-43a2-b0fb-f6a975f78962', 'Jugando Caza Globos con entusiasmo, respetando todas las reglas del juego y aprendiendo a aceptar con deportividad tanto la victoria como la derrota cuando mi globo se revienta.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '5d2d48ed-c461-4a8e-9048-cceecd3de2e2', 'Participando activamente en Caza Globos, donde aprendo a respetar las reglas del juego mientras me divierto corriendo, esquivando y protegiendo mi globo junto a mis compañeros de Manada.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '7200435f-b020-46fc-b323-8249048b1d18', 'Liderando la organización de Caza Globos para mi Avanzada y unidades menores, preparando el campo, explicando las reglas y facilitando que todos disfruten de la actividad de forma segura.') ON CONFLICT DO NOTHING;
