END $$;


-- ==============================================
-- ARTICLE: Cuatro Esquinas (cuatro-esquinas)
-- ==============================================
DO $$
DECLARE
  v_admin_id UUID;
  v_articulo_id UUID;
BEGIN
  SELECT id INTO v_admin_id FROM perfiles WHERE rol_id = 1 LIMIT 1;
  IF v_admin_id IS NULL THEN
    SELECT id INTO v_admin_id FROM perfiles LIMIT 1;
  END IF;

  DELETE FROM articulos WHERE slug = 'cuatro-esquinas';

  v_articulo_id := uuid_generate_v4();

  INSERT INTO articulos (
    id,
    autor_id,
    categoria_id,
    titulo,
    slug,
    contenido,
    extracto,
    imagen_destacada,
    estado,
    etiquetas,
    metadata
  ) VALUES (
    v_articulo_id,
    v_admin_id,
    NULL,
    'Cuatro Esquinas',
    'cuatro-esquinas',
    $html$<h2>📜 Descripción de Las Cuatro Esquinas</h2><p><strong>Cuatro Esquinas</strong> es un vibrante juego scout de campo abierto que combina la velocidad de carrera, la estrategia de lanzamientos y la agilidad de recolección en equipo. Dos patrullas se enfrentan en un cuadrilátero delimitado para desafiar sus reflejos y coordinación.</p><hr><h3>🎲 ¿Cómo se juega Las Cuatro Esquinas?</h3><ol><li><strong>Delimitación del Terreno:</strong> Se delimita un cuadrado de 15 metros por lado colocados en las esquinas cuatro pañolines sobre el césped.</li><li><strong>Formación de Equipos:</strong> El Equipo A (corredores) se alinea fuera del cuadrado en una fila. El Equipo B (defensores) se dispersa tácticamente por el terreno.</li><li><strong>Lanzamiento y Carrera:</strong> El primer corredor del Equipo A lanza la pelota lo más lejos posible dentro del campo y comienza a correr a máxima velocidad alrededor del cuadrado para tocar los cuatro pañolines de las esquinas.</li><li><strong>La Interceptación:</strong> Los defensores del Equipo B deben tomar la pelota lo más rápido posible y, pasándola entre ellos sin dar pasos sosteniendo el balón, intentar quemar o tocar al corredor antes de que complete el recorrido por las cuatro esquinas.</li><li><strong>Rotación:</strong> Una vez que han corrido todos los integrantes de un equipo, se intercambian los roles. Gana el equipo que logre recolectar la mayor cantidad de pañolines completando carreras limpias.</li></ol>$html$,
    'Un vibrante juego scout de campo abierto donde dos equipos compiten lanzando la pelota y corriendo por las esquinas del terreno.',
    '/uploads/actividad_cuatroEsquinas.webp',
    'publicado',
    ARRAY['juego-fisico', 'carrera', 'equipo', 'panolines', 'exterior'],
    $json${"areas": ["corporalidad", "carácter", "sociabilidad"], "lugares": ["Exterior", "campo delimitado"], "cantidad": "06 participantes", "duracion": "20 minutos", "unidades": ["manada", "compañía", "tropa", "avanzada"], "descargas": [], "objetivos": ["Refuerzo de habilidades físicas", "Favorecer el trabajo en equipo", "Estimular la capacidad de reacción", "Estrategia y planificación"], "materiales": ["Pañolines", "Pelota"], "variaciones": "<b>Cuatro Esquinas por Parejas:</b> Los corredores avanzan tomados de la mano, exigiendo una aceleración y coordinación sincronizada entre ambos participantes.<br/><br/>\n\n<b>Carrera Nocturna con Linternas:</b> Se juega al anochecer iluminando únicamente las esquinas con linternas de campamento para agudizar los sentidos.<br/><br/>\n\n<b>Lanzamiento de Pañolín Lastrado:</b> En lugar de una pelota, se utiliza un pañolín con un nudo pesado para exigir precisión en los pases.<br/><br/>\n\n<b>Círculo Interior:</b> El equipo que trata de quemar se coloca dentro del cuadrado de las cuatro esquinas en un círculo, siempre por los bordes del cuadrado, en el centro de ese círculo se posiciona una persona del equipo que está corriendo, el equipo que trata de quemar entonces debe centrarse sólo en quemar al participante que está en el centro del círculo mientras este esquiva el resto de su equipo va recogiendo lo pañolines en las esquinas se los pasa al siguiente en la fila que sale corriendo para dejarlos, y así sucesivamente, se cuentan los puntos por cada recogida y cada retirada de los pañolines en las esquinas.", "recomendaciones": "<b>Seguridad y Pases Limpios:</b> Exigir firmemente que los lanzamientos para tocar al corredor sean suaves y dirigidos del torso hacia abajo. Jamás se permiten lanzamientos a la cabeza.<br/><br/>\n\n<b>Terreno Despejado:</b> Inspeccionar previamente que el cuadrilátero esté libre de piedras o irregularidades que puedan provocar tropezones durante la carrera.<br/><br/>\n\n<b>Animación en Equipo:</b> Motivar a los jugadores en reserva a cantar y animar a sus compañeros de fila durante cada carrera.<br/><br/>", "justificacion_areas": "Cuatro Esquinas estimula la corporalidad al ejercitar la velocidad de aceleración, la precisión de pases y la resistencia física. Fortalece el carácter al promover el sentido del humor y el fair play ante la presión de la carrera, y desarrolla la sociabilidad al afianzar la coordinación táctica y la cooperación entre compañeros.", "objetivos_educativos": [{"id": "0d3af46a-d64c-4e59-a765-1f72dc41ba76", "area": "Sociabilidad", "texto": "Ayudo a mi patrulla en los compromisos que tomamos.", "unidad": "Tropa", "como_se_cumple": "Fomentando la inclusión activa y la cooperación táctica en la patrulla."}, {"id": "117bbf3f-7e3d-4c61-b305-821609bf2e5a", "area": "Carácter", "texto": "Contribuyo al ambiente de alegría de mi Compañía.", "unidad": "Compañía", "como_se_cumple": "Viviendo la competencia fraterna con optimismo y desinhibición."}, {"id": "25b24d3a-9d47-44af-b460-680508e644f3", "area": "Carácter", "texto": "Soy alegre.", "unidad": "Compañía", "como_se_cumple": "Afrontando los momentos intensos del juego con madurez y buen ánimo."}, {"id": "4b2e406f-2d78-4039-9ce2-4ccb743eb553", "area": "Carácter", "texto": "Soy capaz de reírme de mis propios absurdos.", "unidad": "Avanzada", "como_se_cumple": "Propiciando un clima festivo de camaradería y juego limpio."}, {"id": "4bf1e3dd-7f21-4c24-962d-9d6d64e32f25", "area": "Corporalidad", "texto": "Me gusta hacer actividades al aire libre.", "unidad": "Manada", "como_se_cumple": "Corriendo velozmente entre las bases para alcanzar los pañolines en el tiempo límite."}, {"id": "4d66ed86-48ec-4801-bd0a-e5c8d023c8cd", "area": "Carácter", "texto": "Enfrento y resuelvo mis dificultades con alegría.", "unidad": "Tropa", "como_se_cumple": "Aceptando los resultados de cada carrera con sentido del humor y deportividad."}, {"id": "58b4936a-816e-4d17-8d0a-c92d0606009d", "area": "Corporalidad", "texto": "Participo en los juegos, excursiones y campamentos que organiza mi patrulla.", "unidad": "Tropa", "como_se_cumple": "Desarrollando resistencia física y velocidad de reacción en las carreras por equipo."}, {"id": "5abfbe81-75e4-4444-b52d-38e59e8b6ec7", "area": "Sociabilidad", "texto": "Estoy siempre disponible para ayudar a los demás, incluso cuando se trata de tareas pesadas o poco agradables.", "unidad": "Avanzada", "como_se_cumple": "Organizando el juego con sentido de justicia y respeto solidario por todos."}, {"id": "5cbe35dc-d15b-4070-9a36-5b0e652c7946", "area": "Sociabilidad", "texto": "Respeto las opiniones de los demás.", "unidad": "Manada", "como_se_cumple": "Apoyando y colaborando con los compañeros para completar la recolección."}, {"id": "5d2d48ed-c461-4a8e-9048-cceecd3de2e2", "area": "Corporalidad", "texto": "Me gusta jugar con otros niños y niñas y respeto las reglas de los juegos.", "unidad": "Manada", "como_se_cumple": "Ejercitando mi velocidad de aceleración y puntería de lanzamiento al aire libre."}, {"id": "6768d60a-187e-4bbf-97b9-cdc25a316030", "area": "Corporalidad", "texto": "Ayudo a preparar los juegos, excursiones y campamentos de mi patrulla y mi Tropa.", "unidad": "Tropa", "como_se_cumple": "Esforzándome por superar mi rendimiento físico respetando el fair play."}, {"id": "7200435f-b020-46fc-b323-8249048b1d18", "area": "Corporalidad", "texto": "Participo en la organización de juegos y actividades recreativas para los demás.", "unidad": "Avanzada", "como_se_cumple": "Liderando dinámicas de competencia deportiva intensa en el grupo."}, {"id": "8c1cbf88-6e1d-496b-b789-9e0b767c8814", "area": "Carácter", "texto": "Casi siempre estoy alegre.", "unidad": "Manada", "como_se_cumple": "Disfrutando con alegría del juego de carreras sin importar quién gane la ronda."}, {"id": "944660c8-0093-4181-ba2c-5f95cc74ba47", "area": "Sociabilidad", "texto": "No me gusta cuando no se respetan los derechos humanos y lo digo.", "unidad": "Compañía", "como_se_cumple": "Velando por el cumplimiento honesto de las reglas del juego."}, {"id": "9a38e454-f93a-40a5-9f68-e500ba7e0655", "area": "Carácter", "texto": "Comparto mi alegría con mis amigos, amigos y familia.", "unidad": "Tropa", "como_se_cumple": "Animando con energía a los compañeros de equipo durante sus lanzamientos."}, {"id": "a3d7abdf-ca3b-42b8-92b5-403958fb537c", "area": "Sociabilidad", "texto": "Procuro que respetemos a nuestras compañeros, cualquiera sea su manera de ser.", "unidad": "Tropa", "como_se_cumple": "Respetando las decisiones de los árbitros y las reglas del cuadrilátero."}, {"id": "b12da732-d736-480c-82b8-95b312316390", "area": "Corporalidad", "texto": "Me esfuerzo por mejorar mi rendimiento en el deporte que practico y sé ganar y perder.", "unidad": "Compañía", "como_se_cumple": "Coordinando desplazamientos rápidos y estrategias de interceptación."}, {"id": "cfa10133-c25c-4deb-aebe-a00f8fe3f7ef", "area": "Sociabilidad", "texto": "Comparto lo que tengo con mis compañeros y compañeras.", "unidad": "Manada", "como_se_cumple": "Respetando los turnos de carrera de todos los lobatos de la seisena."}, {"id": "d408da3c-207d-4442-a891-8f50efbeecb1", "area": "Carácter", "texto": "Enfrento las dificultades con buen ánimo.", "unidad": "Manada", "como_se_cumple": "Manteniendo un espíritu alegre y entusiasta al recorrer las esquinas."}, {"id": "d5b111f1-5f6f-4716-8a02-e1826d653c59", "area": "Corporalidad", "texto": "Participo en los juegos, excursiones y campamentos que organiza mi patrulla.", "unidad": "Compañía", "como_se_cumple": "Demostrando agilidad corporal y coordinación de pases con la pelota."}, {"id": "fce82191-77ea-444b-89d9-e33b62a323a5", "area": "Sociabilidad", "texto": "Procuro que respetemos a nuestras compañeras, cualquiera sea su manera de ser.", "unidad": "Compañía", "como_se_cumple": "Promoviendo el trabajo en equipo y el apoyo recíproco en el campo."}]}$json$::jsonb
  );

  INSERT INTO articulo_categorias (articulo_id, categoria_id) VALUES (v_articulo_id, 1) ON CONFLICT DO NOTHING;
  INSERT INTO articulo_categorias (articulo_id, categoria_id) VALUES (v_articulo_id, 7) ON CONFLICT DO NOTHING;
