  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '117bbf3f-7e3d-4c61-b305-821609bf2e5a', 'Viviendo la competencia fraterna con optimismo y desinhibición.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '25b24d3a-9d47-44af-b460-680508e644f3', 'Afrontando los momentos intensos del juego con madurez y buen ánimo.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '4b2e406f-2d78-4039-9ce2-4ccb743eb553', 'Propiciando un clima festivo de camaradería y juego limpio.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '4bf1e3dd-7f21-4c24-962d-9d6d64e32f25', 'Corriendo velozmente entre las bases para alcanzar los pañolines en el tiempo límite.') ON CONFLICT DO NOTHING;
