  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, 'd408da3c-207d-4442-a891-8f50efbeecb1', 'Reaccionando con alegría y serenidad ante las sorpresas de la travesía a ciegas.') ON CONFLICT DO NOTHING;
