  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '117bbf3f-7e3d-4c61-b305-821609bf2e5a', 'Viviendo la experiencia con tranquilidad y espontaneidad en el grupo.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '25b24d3a-9d47-44af-b460-680508e644f3', 'Fomentando un clima de distensión y apertura dialogante.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '3a35ddd8-f6dc-4e00-a04d-107a0825bd99', 'Desarrollando serenidad emocional al cerrar los ojos y confiar en la unidad.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '4b2e406f-2d78-4039-9ce2-4ccb743eb553', 'Aceptando la entrega con deportividad y serenidad de carácter.') ON CONFLICT DO NOTHING;
