  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '5abfbe81-75e4-4444-b52d-38e59e8b6ec7', 'Liderando con empatía la contención del grupo para generar seguridad absoluta.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '62876ebe-214f-4caf-b164-664e12fd30ae', 'Aceptando mis vulnerabilidades y confiando en el sostén fraterno de la patrulla.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '8f0eb7d9-c291-44f3-9551-4330c19e0cc2', 'Cultivando la madurez afectiva y la aceptación serena de mis posibilidades personales.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '944660c8-0093-4181-ba2c-5f95cc74ba47', 'Respetando la libertad y el ritmo emocional de cada participante.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '9a38e454-f93a-40a5-9f68-e500ba7e0655', 'Afrontando el reto de soltarse con una actitud serena y positiva.') ON CONFLICT DO NOTHING;
