  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, 'c380e11a-571d-4617-924c-aa933ae30138', 'Fortaleciendo la autoestima al experimentar el cuidado y la protección de mis pares.') ON CONFLICT DO NOTHING;
  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, 'd716bdfb-2fea-4b96-9a46-b86d66692d45', 'Reflexionando sobre la confianza con madurez, templanza y optimismo.') ON CONFLICT DO NOTHING;
