-- ==============================================
-- ARTICLE: El Matamoscas (el-matamoscas)
-- ==============================================
DO $$
DECLARE
  v_admin_id UUID;
  v_articulo_id UUID;
BEGIN
  SELECT id INTO v_admin_id FROM perfiles WHERE rol_id = 1 LIMIT 1;
  IF v_admin_id IS NULL THEN
    SELECT id INTO v_admin_id FROM perfiles LIMIT 1;
  END IF;

  DELETE FROM articulos WHERE slug = 'el-matamoscas';

  v_articulo_id := uuid_generate_v4();

  INSERT INTO articulos (
    id,
    autor_id,
    categoria_id,
    titulo,
    slug,
    contenido,
    extracto,
    imagen_destacada,
    estado,
    etiquetas,
    metadata
  ) VALUES (
    v_articulo_id,
    v_admin_id,
    NULL,
    'El Matamoscas',
    'el-matamoscas',
    $html$<h2>📜 Descripción del Juego</h2><p><strong>El Matamoscas</strong> es un apasionante y enérgico juego scout de persecución al aire libre. Un jugador inicial en el centro del campo intenta atrapar a los demás mientras cruzan de un extremo a otro. Cada jugador atrapado se une de la mano formando una gran cadena humana ("el matamoscas") que debe coordinarse para atrapar al resto de los participantes.</p><hr><h3>🎲 ¿Cómo se juega?</h3><ol><li><strong>Delimitación del Campo:</strong> Se delimita un campo rectangular de aproximadamente 20 por 10 metros con dos líneas de fondo bien marcadas.</li><li><strong>El Matamoscas Inicial:</strong> Todos los participantes se ubican detrás de una línea de fondo. El dirigente o animador designa al primer "matamoscas", quien se coloca en el centro del campo.</li><li><strong>La Carrera y la Captura:</strong> A la señal de partida, todos los jugadores corren hacia la línea de fondo opuesta intentando no ser tocados por el matamoscas.</li><li><strong>Formación de la Cadena:</strong> Cada jugador atrapado debe tomarse de la mano con el matamoscas. La cadena crece progresivamente y sólo los dos jugadores de los extremos de la cadena pueden tocar a los corredores.</li><li><strong>Trabajo en Equipo:</strong> Si la cadena se rompe (se sueltan las manos), no se contabiliza ninguna captura hasta que vuelvan a unirse.</li><li><strong>Ganador:</strong> El juego continúa con carreras sucesivas hasta que todos son atrapados. El último participante en ser atrapado es el ganador.</li></ol>$html$,
    'Un enérgico juego al aire libre donde los participantes atrapados forman una gran cadena humana para cercar al resto.',
    '/uploads/actividad_elMatamoscas.webp',
    'publicado',
    ARRAY['juego-de-persecucion', 'agilidad', 'panolines', 'exterior', 'trabajo-en-equipo'],
    $json${"areas": ["corporalidad", "sociabilidad", "creatividad"], "lugares": ["Exterior", "campo delimitado"], "cantidad": "08 participantes", "duracion": "20 minutos", "unidades": ["manada", "compañía", "tropa", "avanzada"], "descargas": [], "objetivos": ["Agilidad física", "Trabajo en equipo", "Estrategia grupal", "Desarrollo de la coordinación"], "materiales": ["Pañolines", "Sin Materiales"], "variaciones": "<b>Matamoscas Sin Reversa:</b> Los corredores no pueden retroceder una vez que inician la carrera; sólo pueden avanzar hacia adelante o desplazarse lateralmente.<br/><br/>\n\n<b>El Matamoscas Doble:</b> Cuando la cadena alcanza los 8 participantes, se divide obligatoriamente en dos cadenas independientes de 4 personas, aumentando la agilidad y estrategia del juego.<br/><br/>\n\n<b>Variante con Pañolín:</b> Cada corredor lleva un <b>pañolín</b> en el cinturón. La cadena debe arrebatar los <b>pañolines</b> en lugar de sólo tocar a los participantes.<br/><br/>", "recomendaciones": "<b>Seguridad en el Terreno:</b> Verificar que el terreno de juego esté despejado de piedras, raíces o baches para evitar caídas durante las maniobras rápidas.<br/><br/>\n\n<b>Coordinación de los Extremos:</b> Recordar a los participantes de la cadena que deben correr a un ritmo parejo para evitar tirones bruscos en los brazos.<br/><br/>\n\n<b>Rol del Dirigente:</b> Animar el juego con dinamismo y vigilar que la cadena respete la regla de no soltarse las manos al efectuar las capturas.", "justificacion_areas": "El Matamoscas estimula la corporalidad al exigir velocidad, resistencia cardiovascular y reflejos motoras en cada carrera. Desarrolla la sociabilidad al requerir trabajo en equipo y sincronización perfecta entre los miembros de la cadena humana, y potencia la creatividad al demandar tácticas rápidas de esquiva y cerco estratégico.", "objetivos_educativos": [{"id": "0d3af46a-d64c-4e59-a765-1f72dc41ba76", "area": "Sociabilidad", "texto": "Ayudo a mi patrulla en los compromisos que tomamos.", "unidad": "Tropa", "como_se_cumple": "Fomentando el trabajo en equipo y la cooperación activa en la cadena."}, {"id": "47e7e2d8-12cd-447d-8df4-251e83aa547b", "area": "Creatividad", "texto": "Trato de hablar claro y conocer nuevas palabras.", "unidad": "Manada", "como_se_cumple": "Creando tácticas rápidas de huida o cerco según el ancho del terreno."}, {"id": "4bf1e3dd-7f21-4c24-962d-9d6d64e32f25", "area": "Corporalidad", "texto": "Me gusta hacer actividades al aire libre.", "unidad": "Manada", "como_se_cumple": "Desarrollando velocidad, agilidad y reflejos al esquivar a la cadena atrapadora."}, {"id": "58b4936a-816e-4d17-8d0a-c92d0606009d", "area": "Corporalidad", "texto": "Participo en los juegos, excursiones y campamentos que organiza mi patrulla.", "unidad": "Tropa", "como_se_cumple": "Aumentando la destreza cardiovascular y los reflejos de desplazamiento en el campo."}, {"id": "5abfbe81-75e4-4444-b52d-38e59e8b6ec7", "area": "Sociabilidad", "texto": "Estoy siempre disponible para ayudar a los demás, incluso cuando se trata de tareas pesadas o poco agradables.", "unidad": "Avanzada", "como_se_cumple": "Liderando con tacto estratégico el avance armónico de la cadena de captura."}, {"id": "5cbe35dc-d15b-4070-9a36-5b0e652c7946", "area": "Sociabilidad", "texto": "Respeto las opiniones de los demás.", "unidad": "Manada", "como_se_cumple": "Coordinando los giros de la cadena para que ningún lobato se quede atrás."}, {"id": "5d2d48ed-c461-4a8e-9048-cceecd3de2e2", "area": "Corporalidad", "texto": "Me gusta jugar con otros niños y niñas y respeto las reglas de los juegos.", "unidad": "Manada", "como_se_cumple": "Ejercitando la resistencia física y la coordinación motoras en carreras continuas."}, {"id": "6768d60a-187e-4bbf-97b9-cdc25a316030", "area": "Corporalidad", "texto": "Ayudo a preparar los juegos, excursiones y campamentos de mi patrulla y mi Tropa.", "unidad": "Tropa", "como_se_cumple": "Fortaleciendo la agilidad corporal y el dominio de movimientos bruscos."}, {"id": "7200435f-b020-46fc-b323-8249048b1d18", "area": "Corporalidad", "texto": "Participo en la organización de juegos y actividades recreativas para los demás.", "unidad": "Avanzada", "como_se_cumple": "Manteniendo un excelente estado físico y resistencia durante el esfuerzo intensivo."}, {"id": "944660c8-0093-4181-ba2c-5f95cc74ba47", "area": "Sociabilidad", "texto": "No me gusta cuando no se respetan los derechos humanos y lo digo.", "unidad": "Compañía", "como_se_cumple": "Fortaleciendo la cohesión grupal y la toma de decisiones colaborativa."}, {"id": "981fa19b-7f60-4e0e-b2fa-16123df5e37e", "area": "Creatividad", "texto": "Expreso mis pensamientos y experiencias en el Tally.", "unidad": "Tropa", "como_se_cumple": "Buscando trayectorias innovadoras para romper la cobertura del equipo atrapador."}, {"id": "a3d7abdf-ca3b-42b8-92b5-403958fb537c", "area": "Sociabilidad", "texto": "Procuro que respetemos a nuestras compañeros, cualquiera sea su manera de ser.", "unidad": "Tropa", "como_se_cumple": "Actuando de manera coordinada con la patrulla para cercar a los corredores."}, {"id": "b12da732-d736-480c-82b8-95b312316390", "area": "Corporalidad", "texto": "Me esfuerzo por mejorar mi rendimiento en el deporte que practico y sé ganar y perder.", "unidad": "Compañía", "como_se_cumple": "Canalizando la energía física en un ejercicio dinámico y saludable."}, {"id": "beb4b3e4-fe1c-4f06-af34-2c7f88202eb7", "area": "Creatividad", "texto": "Me gusta cantar y conozco muchas canciones.", "unidad": "Compañía", "como_se_cumple": "Adaptando estrategias de desplazamiento en tiempo real según el avance de la cadena."}, {"id": "cfa10133-c25c-4deb-aebe-a00f8fe3f7ef", "area": "Sociabilidad", "texto": "Comparto lo que tengo con mis compañeros y compañeras.", "unidad": "Manada", "como_se_cumple": "Tomándome de las manos con mis compañeros para atrapar en equipo sin soltarnos."}, {"id": "d252cb51-c224-4528-90b3-e0288aa343dd", "area": "Creatividad", "texto": "Comparto con los demás mis inquietudes, aspiraciones y creaciones artísticas.", "unidad": "Avanzada", "como_se_cumple": "Optimizando la cobertura del campo mediante tácticas grupales envolventes."}, {"id": "d581cfa7-db1f-4b08-b4d3-525b23e418ea", "area": "Creatividad", "texto": "Participo con entusiasmo en las actividades artísticas de mi Compañía.", "unidad": "Compañía", "como_se_cumple": "Anticipando los movimientos del oponente para ajustar la ruta de escape."}, {"id": "d5b111f1-5f6f-4716-8a02-e1826d653c59", "area": "Corporalidad", "texto": "Participo en los juegos, excursiones y campamentos que organiza mi patrulla.", "unidad": "Compañía", "como_se_cumple": "Mejorando la capacidad física y el tiempo de reacción al esquivar oponentes."}, {"id": "e5eada78-3a2d-467e-8d15-da159b60552f", "area": "Creatividad", "texto": "Me gusta dibujar y pintar.", "unidad": "Manada", "como_se_cumple": "Ideando amagos de carrera para engañar a la cadena y cruzar la línea a salvo."}, {"id": "f9cea3e0-24f4-43ab-9efb-1a4541a29943", "area": "Creatividad", "texto": "Ayudo a preparar materiales para las representaciones artísticas.", "unidad": "Tropa", "como_se_cumple": "Diseñando maniobras en tenaza para encerrar a los corredores más veloces."}, {"id": "fce82191-77ea-444b-89d9-e33b62a323a5", "area": "Sociabilidad", "texto": "Procuro que respetemos a nuestras compañeras, cualquiera sea su manera de ser.", "unidad": "Compañía", "como_se_cumple": "Sincronizando el desplazamiento colectivo con respeto y apoyo recíproco."}]}$json$::jsonb
